</div>
<script>
(() => {
  const K = window.LabKit, root = document.getElementById('mlp-lab');
  const $ = s => root.querySelector(s);
  function gen(kind, n, seed) {
    const r = K.rng(seed), P = [];
    for (let i = 0; i < n; i++) {
      if (kind === 'xor') { const a = r() * 2 - 1, b = r() * 2 - 1; P.push([a, b, (a > 0) !== (b > 0) ? 1 : 0]); }
      else if (kind === 'circ') { const a = r() * 2 - 1, b = r() * 2 - 1; P.push([a, b, a * a + b * b < 0.42 ? 1 : 0]); }
      else if (kind === 'lunas') { const c = i % 2, t = r() * Math.PI, nx = 0.1 * r.normal(), ny = 0.1 * r.normal();
        P.push(c ? [0.5 * (1 - Math.cos(t)) - 0.25 + nx, 0.5 * (0.25 - Math.sin(t)) + ny, 1] : [0.5 * Math.cos(t) - 0.25 + nx, 0.5 * Math.sin(t) - 0.12 + ny, 0]); }
      else { const c = i % 2, t = 0.3 + r() * 5.2, rad = t / 5.6; const ang = t * 2.1 + c * Math.PI; P.push([rad * Math.cos(ang) + 0.04 * r.normal(), rad * Math.sin(ang) + 0.04 * r.normal(), c]); }
    }
    return P;
  }
  const act = { tanh: [Math.tanh, a => 1 - a * a], relu: [z => Math.max(0, z), a => (a > 0 ? 1 : 0)], sig: [z => 1 / (1 + Math.exp(-z)), a => a * (1 - a)] };
  const sig = z => 1 / (1 + Math.exp(-z));
  let TR, TE, net, ep, hist, timer = null;
  const dataSeg = K.segmented($('#mlp-data'), () => { stop(); init(); render(); });
  const actSeg = K.segmented($('#mlp-act'), () => { stop(); initNet(); render(); });
  function init() { const k = dataSeg.get(); TR = gen(k, 160, 7); TE = gen(k, 160, 8); initNet(); }
  function initNet() {
    const H = +$('#mlp-h').value, r = K.rng(42), s = 1;
    net = { H, W1: Array.from({ length: H }, () => [r.normal() * s, r.normal() * s]), b1: Array(H).fill(0).map(() => 0.1 * r.normal()), W2: Array.from({ length: H }, () => r.normal() * s / Math.sqrt(H)), b2: 0 };
    ep = 0; hist = [];
  }
  function forward(p) { const f = act[actSeg.get()][0], h = net.W1.map((w, j) => f(w[0] * p[0] + w[1] * p[1] + net.b1[j])); let z = net.b2; h.forEach((v, j) => { z += net.W2[j] * v; }); return { h, y: sig(z) }; }
  const lossOf = set => K.mean(set.map(p => { const y = K.clamp(forward(p).y, 1e-9, 1 - 1e-9); return -(p[2] * Math.log(y) + (1 - p[2]) * Math.log(1 - y)); }));
  const accOf = set => set.filter(p => (forward(p).y >= 0.5 ? 1 : 0) === p[2]).length / set.length;
  function epoch() {
    const H = net.H, d = act[actSeg.get()][1], lr = 10 ** +$('#mlp-lr').value, gW1 = net.W1.map(() => [0, 0]), gb1 = Array(H).fill(0), gW2 = Array(H).fill(0); let gb2 = 0;
    TR.forEach(p => { const { h, y } = forward(p), d2 = y - p[2]; gb2 += d2;
      for (let j = 0; j < H; j++) { gW2[j] += d2 * h[j]; const d1 = d2 * net.W2[j] * d(h[j]); gb1[j] += d1; gW1[j][0] += d1 * p[0]; gW1[j][1] += d1 * p[1]; } });
    const n = TR.length;
    for (let j = 0; j < H; j++) { net.W2[j] -= lr * gW2[j] / n; net.b1[j] -= lr * gb1[j] / n; net.W1[j][0] -= lr * gW1[j][0] / n; net.W1[j][1] -= lr * gW1[j][1] / n; }
    net.b2 -= lr * gb2 / n; ep++;
    if (ep % 10 === 0 || ep < 10) hist.push([ep, lossOf(TR), lossOf(TE)]);
  }
  function stop() { if (timer) { clearInterval(timer); timer = null; $('#mlp-play').textContent = '▶ Entrenar'; } }
  $('#mlp-play').addEventListener('click', () => { if (timer) { stop(); return; } $('#mlp-play').textContent = '❚❚ Pausa'; timer = setInterval(() => { for (let k = 0; k < 20; k++) epoch(); render(); if (ep >= 5000) stop(); }, 40); });
  $('#mlp-100').addEventListener('click', () => { for (let k = 0; k < 100; k++) epoch(); render(); });
  $('#mlp-reset').addEventListener('click', () => { stop(); initNet(); render(); });
  $('#mlp-h').addEventListener('input', () => { stop(); initNet(); render(); });
  $('#mlp-lr').addEventListener('input', render);
  function render() {
    $('#mlp-h-v').textContent = net.H; $('#mlp-lr-v').textContent = K.fmt(10 ** +$('#mlp-lr').value, 2);
    const lTr = lossOf(TR), aTr = accOf(TR), aTe = accOf(TE);
    $('#mlp-ep').textContent = ep; $('#mlp-loss').textContent = K.fmt(lTr, 3); $('#mlp-tr').textContent = K.fmt(aTr, 3); $('#mlp-te').textContent = K.fmt(aTe, 3);
    const c = K.chart($('#mlp-svg'), { width: 360, height: 360, x: [-1.2, 1.2], y: [-1.2, 1.2], margin: { left: 30, right: 8, top: 8, bottom: 30 } });
    const G = 36, st = 2.4 / G;
    for (let i = 0; i < G; i++) for (let j = 0; j < G; j++) { const p = [-1.2 + (i + 0.5) * st, -1.2 + (j + 0.5) * st], y = forward(p).y;
      const rc = c.rect(p[0] - st / 2, p[1] - st / 2, p[0] + st / 2, p[1] + st / 2, y >= 0.5 ? 's1' : 's2'); rc.style.stroke = 'none'; rc.style.fillOpacity = 0.05 + 0.3 * Math.abs(y - 0.5) * 2; }
    c.axes({ xTicks: 4, yTicks: 4, grid: false, xFmt: v => K.fmt(v, 1), yFmt: v => K.fmt(v, 1) });
    TR.forEach(p => c.dot(p[0], p[1], 3, (p[2] ? 's1' : 's2') + ' dot'));
    TE.slice(0, 60).forEach(p => { const d = c.dot(p[0], p[1], 3.2, (p[2] ? 's1' : 's2') + ' dot'); d.style.stroke = 'var(--lab-text)'; d.style.strokeWidth = 1; });
    const H = hist.length ? hist : [[0, lTr, lossOf(TE)]], ymax = Math.max(0.8, ...H.map(h => Math.max(h[1], h[2]))) * 1.05;
    const cc = K.chart($('#mlp-curve'), { width: 360, height: 240, x: [0, Math.max(100, ep)], y: [0, ymax], margin: { left: 40, bottom: 36 } });
    cc.axes({ xTicks: 4, yTicks: 4, xLabel: 'época', yLabel: 'entropía cruzada', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 1) });
    cc.path(H.map(h => [h[0], h[1]]), 's1 line'); cc.path(H.map(h => [h[0], h[2]]), 's4 line');
    const note = $('#mlp-note');
    if (net.H === 1 && dataSeg.get() !== 'lunas') { note.className = 'plab-note warn'; note.textContent = 'Con una sola neurona oculta la frontera es (casi) una recta: la red no puede ser mejor que un modelo lineal. Agrega neuronas.'; }
    else if (ep === 0) { note.className = 'plab-note'; note.textContent = 'Pesos aleatorios: la frontera inicial no tiene relación con los datos. Pulsa ▶ Entrenar.'; }
    else { note.className = aTe >= 0.9 ? 'plab-note good' : 'plab-note'; note.textContent = `Época ${ep}: exactitud ${K.fmt(aTr, 3)} en entrenamiento y ${K.fmt(aTe, 3)} en prueba. ` + (aTr - aTe > 0.08 ? 'La brecha indica sobreajuste.' : dataSeg.get() === 'espiral' && net.H < 8 ? 'La espiral necesita muchas neuronas y paciencia.' : 'Cada neurona oculta aporta un «pliegue» a la frontera.'); }
  }
  init(); render();
})();
