    "Diagonal":         np.array([[2, 1, -1], [1, 0, -1], [-1, -1, -2]], dtype=float),
    "Blob (Lap.)":      np.array([[0, 1, 0], [1, -4, 1], [0, 1, 0]], dtype=float),
